PuzzleBank.setSearch("zh", {
  "geo-ambiguous-ssa": {"t":"一组条件，两个三角形","s":"在三角形 $ABC$ 中，$a = \\sqrt3$，$b = \\sqrt2$，$B = 45^\\circ$（边 $a$ 对角 $A$，边 $b$ 对角 $B$）。<b>角 $A$ 可能是下列哪些？</b>","k":"在三角形 ABC 中， a = 3 ， b = 2 ， B = 45° （边 a 对角 A ，边 b 对角 B ）。 角 A 可能是下列哪些？ 边 BC = a = √3 水平，B 在左侧。从 B 出发的射线与 BC 成 45°。以 C 为圆心、b = √2 为半径的圆与射线交于两点，得到顶点 A 的两个可能位置 A1 和 A2。 正弦定理给出 sin A —— 而一个正弦值对应两个角。 正弦定理 两个可能的角 两种都可能吗？ 两个三角形 逐项检查选项"},
  "geo-chord-inscribed-angle": {"t":"长为 8 的弦","s":"圆 $O$ 的半径为 $5$，弦 $AB = 8$。点 $C$ 在优弧 $AB$ 上。<b>下列说法中正确的是？</b>","k":"圆 O 的半径为 5 ，弦 AB = 8 。点 C 在优弧 AB 上。 下列说法中正确的是？ 圆心为 O、半径为 5 的圆。一条长为 8 的水平弦 AB 位于圆心下方。C 是上方优弧上的一点，构成圆周角 ACB。 从 O 向 AB 作垂线：它平分弦。 从圆心作垂线 圆心角 圆周角 AOB 的面积 逐项检查选项"},
  "geo-cube-diagonal": {"t":"正方体的对角线","s":"正方体 $ABCD\\text{-}A_1B_1C_1D_1$ 的棱长为 $2$。设 $\\theta$ 为体对角线 $AC_1$ 与底面 $ABCD$ 所成的角。<b>下列说法中正确的是？</b>","k":"正方体 ABCD - A 1B 1C 1D 1 的棱长为 2 。设 为体对角线 AC 1 与底面 ABCD 所成的角。 下列说法中正确的是？ 斜二测画法的正方体：底面 ABCD 在下（A 左前，B 右前，C 右后，D 左后），顶面 A1B1C1D1。体对角线从 A 到 C1。棱长 2。 AC 1 在底面上的射影是面对角线 AC 。 面对角线 体对角线 与底面所成的角 表面积与体积 逐项检查选项"},
  "geo-ellipse-focal-60": {"t":"椭圆的焦点三角形","s":"对于椭圆 $\\dfrac{x^2}{25} + \\dfrac{y^2}{9} = 1$，焦点为 $F_1, F_2$，椭圆上一点 $P$ 满足 $\\angle F_1PF_2 = 60^\\circ$。<b>下列说法中正确的是？</b>","k":"对于椭圆 x 2 25 + y 2 9 = 1 ，焦点为 F 1, F 2 ，椭圆上一点 P 满足 F 1PF 2 = 60° 。 下列说法中正确的是？ 以原点为中心的椭圆 x²/25 + y²/9 = 1，焦点 F1(−4, 0) 和 F2(4, 0)，椭圆上第一象限内一点 P 满足角 F1PF2 = 60°。 把 |PF 1| + |PF 2| = 2a 与 F 1PF 2 中的余弦定理结合使用。 读出 a 、 b 、 c 椭圆的定义 在 P 处用余弦定理 面积 逐项检查选项"},
  "geo-incircle-6-8-10": {"t":"直角三角形中的圆","s":"三角形 $ABC$ 在 $C$ 处为直角，$AC = 6$，$BC = 8$。以 $I$ 为圆心的圆内切于三角形，与三边都相切。<b>下列哪些等于该圆的半径 $r$？</b>","k":"三角形 ABC 在 C 处为直角， AC = 6 ， BC = 8 。以 I 为圆心的圆内切于三角形，与三边都相切。 下列哪些等于该圆的半径 r ？ 直角三角形 ABC，直角在 C。直角边 AC = 6 竖直，直角边 BC = 8 水平，斜边 AB 未给出。以 I 为圆心的圆内切于三角形（与三边都相切）；半径 r 从 I 画到边 BC。 把 I 与三个顶点相连：三角形被分成三个高都为 r 的三角形。 求斜边 三角形的面积 从内心 I 分割三角形 半周长 求 r 用切线长验证 逐项检查选项"},
  "geo-law-cosines-120": {"t":"120° 的钝角","s":"在三角形 $ABC$ 中，$AB = 3$，$AC = 5$，$\\angle A = 120^\\circ$。<b>下列说法中正确的是？</b>","k":"在三角形 ABC 中， AB = 3 ， AC = 5 ， A = 120° 。 下列说法中正确的是？ 三角形 ABC，底边 AB = 3，AC = 5，两者夹钝角 A = 120°；边 BC 未知。 对 BC 用余弦定理；记住 cos 120° = - 12 。 余弦定理 面积 其余各角（正弦定理） 外接圆半径与周长 逐项检查选项"},
  "geo-lens-two-quarters": {"t":"正方形中的叶形","s":"在边长为 $4$ 的正方形 $ABCD$ 中，画两个半径为 $4$ 的四分之一圆：一个以 $A$ 为圆心，一个以 $C$ 为圆心，都从 $B$ 到 $D$。<b>下列哪些等于它们之间阴影“叶形”的面积？</b>","k":"在边长为 4 的正方形 ABCD 中，画两个半径为 4 的四分之一圆：一个以 A 为圆心，一个以 C 为圆心，都从 B 到 D 。 下列哪些等于它们之间阴影“叶形”的面积？ 边长为 4 的正方形 ABCD（A 在左下，C 在右上）。以 A 为圆心的四分之一圆从 B 到 D，以 C 为圆心的另一个也从 B 到 D；两段弧之间的叶形区域涂有阴影。 叶形是被对角线 BD 截出的两个弓形。 一个四分之一圆 减去三角形 ABD 两个弓形 用容斥原理验证 逐项检查选项"},
  "geo-parabola-focal-chord": {"t":"过焦点的弦","s":"过抛物线 $y^2 = 4x$ 的焦点 $F$ 且斜率为 $1$ 的直线与抛物线交于 $A$、$B$ 两点。<b>$|AB|$ 等于多少？</b>","k":"过抛物线 y 2 = 4x 的焦点 F 且斜率为 1 的直线与抛物线交于 A 、 B 两点。 |AB| 等于多少？ 开口向右的抛物线 y² = 4x，焦点 F(1, 0)，准线 x = −1。过 F 且斜率为 1 的直线与抛物线交于 A（右上）和 B（靠近顶点）。 对于过焦点的弦， |AB| = x 1 + x 2 + p （到准线的距离）。 焦点与直线 求交点 到准线的距离 用角的公式验证 逐项检查选项"},
  "geo-regular-tetrahedron": {"t":"正四面体及其外接球","s":"正四面体 $ABCD$ 的所有棱长都等于 $2$。<b>下列说法中正确的是？</b>（$V$ 为其体积，$R$ 为其外接球半径。）","k":"正四面体 ABCD 的所有棱长都等于 2 。 下列说法中正确的是？ （ V 为其体积， R 为其外接球半径。） 顶点 A 位于三角形底面 BCD 上方的正四面体（D 在后方，其棱用虚线画出）。O 是底面中心；高 AO 用虚线画出。外接球球心在 AO 上。 高的垂足 O 是底面的重心， BO = 2 3 3 。 底面积与重心 高 体积 外接球 逐项检查选项"},
  "geo-similar-parallel": {"t":"被平行线截","s":"在三角形 $ABC$ 中，$D$ 在 $AB$ 上，$E$ 在 $AC$ 上，$DE \\parallel BC$ 且 $AD : DB = 2 : 3$。$\\triangle ADE$ 的面积为 $8$。<b>$\\triangle ABC$ 的面积是多少？</b>","k":"在三角形 ABC 中， D 在 AB 上， E 在 AC 上， DE BC 且 AD : DB = 2 : 3 。 ADE 的面积为 8 。 ABC 的面积是多少？ 三角形 ABC，顶点 A 在上，底边 BC 在下。与 BC 平行的线段 DE 截 AB 和 AC 两边，AD : DB = 2 : 3。上方的小三角形 ADE 面积为 8。 相似三角形：面积之比等于边长之比的平方。 相似三角形 面积按平方缩放 梯形 逐项检查选项"},
  "geo-vector-dot-square": {"t":"正方形中的数量积","s":"正方形 $ABCD$ 的边长为 $2$，$E$ 是 $CD$ 的中点。<b>$\\overrightarrow{AE}\\cdot\\overrightarrow{BD}$ 等于多少？</b>","k":"正方形 ABCD 的边长为 2 ， E 是 CD 的中点。 AE · BD 等于多少？ 边长为 2 的正方形 ABCD：A 左下，B 右下，C 右上，D 左上。E 是上边 CD 的中点。向量 AE 和 BD 用箭头画出。 以 A 为原点， B = (2,0) ， D = (0,2) 。 坐标 两个向量 数量积 不用坐标 逐项检查选项"},
  "trig-tower-30-60": {"t":"两次仰望的塔","s":"在平地上的点 $P$ 处，望见一座竖直塔的塔顶 $T$ 的仰角为 $30^\\circ$。朝塔直走 $20$ m 到达 $Q$ 后，仰角变为 $60^\\circ$。<b>下列哪些等于塔高 $h$（单位：米）？</b>","k":"在平地上的点 P 处，望见一座竖直塔的塔顶 T 的仰角为 30° 。朝塔直走 20 m 到达 Q 后，仰角变为 60° 。 下列哪些等于塔高 h （单位：米）？ 平地上依次有点 P、Q 和塔底 F。PQ = 20 m，QF = x 未知。高为 h 的塔 FT 竖直。从 P 看 T 的仰角为 30°，从 Q 看为 60°。 看看三角形 PQT 的各角 —— 其中两个相等。 三角形 PQT 的各角 两角相等 → 两边相等 直角三角形 QFT 用两条切线验证 逐项检查选项"},
  "alg-rectangle-area-40": {"t":"长三米","s":"一个矩形的长比宽 $w$ 多 $3$，面积为 $40$。<b>下列哪些等于 $w$？</b>","k":"一个矩形的长比宽 w 多 3 ，面积为 40 。 下列哪些等于 w ？ 宽为 w（短边）、长为 w + 3（长边）的矩形；内部面积为 40。 把面积写成 w(w+3) ，解这个二次方程。 把文字转化为方程 因式分解 保留有意义的根 用求根公式得到同样的答案 逐项检查选项"},
  "mat-cramer-2x2": {"t":"克拉默法则","s":"用行列式解方程组 $\\begin{cases} 2x + 3y = 8 \\\\ x - y = -1 \\end{cases}$。设 $D$ 为系数矩阵的行列式。<b>下列说法中正确的是？</b>","k":"用行列式解方程组 cases 2x + 3y = 8 \\\\ x - y = -1 cases 。设 D 为系数矩阵的行列式。 下列说法中正确的是？ 坐标轴上画有直线 2x + 3y = 8 和 x − y = −1，它们交于点 (1, 2)。角落里写着系数矩阵 (2 3; 1 −1)。 x = D x D ， y = D y D ，其中 D x （ D y ）是把 D 中 x 列（ y 列）换成常数 8, -1 后的行列式。 把方程组写成矩阵形式 替换 x 列 替换 y 列 在图上验证 逐项检查选项"},
  "mat-det-3x3-cofactor": {"t":"一个 3×3 行列式","s":"设 $A = \\begin{pmatrix} 2 & 1 & 3 \\\\ 0 & 4 & 5 \\\\ 1 & 0 & 6 \\end{pmatrix}$。<b>下列哪一项正确？</b>","k":"设 A = pmatrix 2 & 1 & 3 \\\\ 0 & 4 & 5 \\\\ 1 & 0 & 6 pmatrix 。 下列哪一项正确？ 3×3 矩阵 A，各行为 (2, 1, 3)、(0, 4, 5)、(1, 0, 6)，写在括号中。 按第一列展开：其中有一个 0 ，所以只需要两个 2 2 余子式。 按第一列展开 两个余子式 用萨吕法则验证 逐项检查选项"},
  "mat-det-parallelogram-area": {"t":"藏在行列式里的面积","s":"向量 $\\vec u = (3, 1)$ 和 $\\vec v = (1, 2)$ 张成一个平行四边形。<b>下列哪些等于它的面积？</b>","k":"向量 u = (3, 1) 和 v = (1, 2) 张成一个平行四边形。 下列哪些等于它的面积？ 单位方格。从原点 O 出发，向量 u 指向 (3, 1)，向量 v 指向 (1, 2)；平行四边形 O、(3, 1)、(4, 3)、(1, 2) 涂有阴影。 把 u 和 v 作为 2 2 矩阵的两列：面积就是它的行列式的绝对值。 把向量作为列 计算行列式 用外接矩形法验证 逐项检查选项"},
  "mat-det-properties": {"t":"缩放一个 3×3 矩阵","s":"$A$ 是一个 $3\\times3$ 矩阵，$\\det A = 2$。<b>下列说法中正确的是？</b>","k":"A 是一个 3 3 矩阵， A = 2 。 下列说法中正确的是？ 一个体积为 V 的小正方体和一个宽度为其 3 倍、体积为 27V 的正方体：三个方向都放大 3 倍，体积（以及 3×3 行列式）就乘以 3³ = 27。 把一行乘以 3 ，行列式就乘以 3 。 3A 把几行都乘了 3 ？ 一次一行 逆矩阵 其他规则 逐项检查选项"},
  "mat-eigenvalues-2x2": {"t":"不会转向的方向","s":"设 $A = \\begin{pmatrix} 4 & 1 \\\\ 2 & 3 \\end{pmatrix}$。<b>下列哪些是 $A$ 的特征值？</b>","k":"设 A = pmatrix 4 & 1 \\\\ 2 & 3 pmatrix 。 下列哪些是 A 的特征值？ 坐标轴。向量 v = (1, 1) 与它的像 Av = (5, 5) 在同一直线上；向量 w = (1, −2) 与它的像 Aw = (2, −4) 也在同一直线上。 解关于 的二次方程 (A - I) = 0 。 特征方程 解二次方程 在图上看 用迹和行列式验证 逐项检查选项"},
  "mat-inverse-2x2": {"t":"撤销这个矩阵","s":"设 $A = \\begin{pmatrix} 4 & 7 \\\\ 2 & 6 \\end{pmatrix}$。<b>下列哪些等于 $A^{-1}$？</b>","k":"设 A = pmatrix 4 & 7 \\\\ 2 & 6 pmatrix 。 下列哪些等于 A -1 ？ 矩阵 A = (4 7; 2 6)。箭头说明求逆的做法：交换主对角线上的 4 和 6，并改变 7 和 2 的符号。 对于 pmatrix a & b \\\\ c & d pmatrix ，逆矩阵为 1 ad - bc pmatrix d & -b \\\\ -c & a pmatrix 。 它可逆吗？ 交换、变号、相除 验证：乘积是单位矩阵 逐项检查选项"},
  "mat-product-order": {"t":"顺序很重要","s":"设 $A = \\begin{pmatrix} 1 & 2 \\\\ 0 & 1 \\end{pmatrix}$，$B = \\begin{pmatrix} 1 & 0 \\\\ 3 & 1 \\end{pmatrix}$。<b>下列说法中正确的是？</b>","k":"设 A = pmatrix 1 & 2 \\\\ 0 & 1 pmatrix ， B = pmatrix 1 & 0 \\\\ 3 & 1 pmatrix 。 下列说法中正确的是？ 矩阵 A = (1 2; 0 1) 和 B = (1 0; 3 1) 并排写出，准备按“行乘列”相乘。 AB 的 (i, j) 元是 A 的第 i 行乘 B 的第 j 列。再用同样方法算 BA 并比较。 行乘列 再换个顺序 行列式相同 逐项检查选项"},
  "mat-rotation-cube": {"t":"转三次 60°","s":"$R = \\begin{pmatrix} \\cos 60^\\circ & -\\sin 60^\\circ \\\\ \\sin 60^\\circ & \\cos 60^\\circ \\end{pmatrix}$ 把平面旋转 $60^\\circ$，$I$ 为单位矩阵。<b>下列哪些等于 $R^3$？</b>","k":"R = pmatrix cos 60° & - sin 60° \\\\ sin 60° & cos 60° pmatrix 把平面旋转 60° ， I 为单位矩阵。 下列哪些等于 R 3 ？ 以原点为圆心的圆。点 P = (1, 0) 每次旋转 60°，共三次：到 60° 处的 RP、120° 处的 R²P，以及 180° 处的 R³P，即 −P。 连续旋转三次，相当于旋转三倍的角度。 写出 R 旋转角相加 三次即半圈 乘出来验证 逐项检查选项"},
  "mat-shear-power": {"t":"错切十次","s":"设 $A = \\begin{pmatrix} 1 & 1 \\\\ 0 & 1 \\end{pmatrix}$。<b>下列哪一个等于 $A^{10}$？</b>","k":"设 A = pmatrix 1 & 1 \\\\ 0 & 1 pmatrix 。 下列哪一个等于 A 10 ？ 一个正方形及其在 A 和 A² 下的像：底边相同，上边每次再向右滑动一个边长的平行四边形。 先算 A 2 和 A 3 ，找出规律，再直接写出 10 次幂。 前几次幂 规律 滑动十次 逐项检查选项"},
  "mat-singular-parameter": {"t":"逆矩阵何时消失？","s":"当 $k$ 取何值时，$M = \\begin{pmatrix} 1 & 2 & 3 \\\\ 2 & k & 6 \\\\ 1 & 1 & k \\end{pmatrix}$ <b>不</b>可逆？<b>下列哪些是这样的值？</b>","k":"当 k 取何值时， M = pmatrix 1 & 2 & 3 \\\\ 2 & k & 6 \\\\ 1 & 1 & k pmatrix 不 可逆？ 下列哪些是这样的值？ 3×3 矩阵 M，各行为 (1, 2, 3)、(2, k, 6)、(1, 1, k)；两个 k 被突出显示。 方阵不可逆当且仅当其行列式为 0 。按第一行展开。 不可逆即行列式为零 按第一行展开 求根 看出线性相关的行 逐项检查选项"},
  "cx-argument-quadrant": {"t":"它指向哪里？","s":"<b>下列哪些是 $z = -1 + \\sqrt3\\, i$ 的辐角？</b>（角度从正实轴量起。）","k":"下列哪些是 z = -1 + 3\\, i 的辐角？ （角度从正实轴量起。） 复平面第二象限中的 z = −1 + √3 i，到原点距离为 2；标出了从正实轴量起的角。 画个图：实部为负、虚部为正，所以角在 90° 和 180° 之间。 确定象限 模与角 计算器为什么会错 逐项检查选项"},
  "cx-conjugate-facts": {"t":"一个数和它的镜像","s":"设 $z = 2 - 3i$，$\\bar z$ 为它的共轭。<b>下列说法中正确的是？</b>","k":"设 z = 2 - 3i ， z 为它的共轭。 下列说法中正确的是？ 复平面上的 z = 2 − 3i 及其共轭 2 + 3i，关于实轴对称。 z = 2 + 3i ：只改变虚部的符号。 共轭 和与积 其他量 逐项检查选项"},
  "cx-de-moivre-power": {"t":"幂的螺旋","s":"<b>下列哪些等于 $(1 + i)^8$？</b>","k":"下列哪些等于 (1 + i) 8 ？ 复平面上的 1 + i 及其幂 (1 + i)² = 2i、(1 + i)³ = −2 + 2i、(1 + i)⁴ = −4：每一步旋转 45° 并放大 √2 倍。 把 1 + i 写成极坐标形式：模 2 ，辐角 45° 。求幂会使角度成倍增加。 极坐标形式 棣莫弗公式 用平方验证 逐项检查选项"},
  "cx-division-conjugate": {"t":"除以一个复数","s":"<b>下列哪一个等于 $\\dfrac{5 + 5i}{1 + 2i}$？</b>","k":"下列哪一个等于 5 + 5i 1 + 2i ？ 复平面上的 5 + 5i、1 + 2i 以及商 3 − i，各点都与原点相连。 分子分母同乘 1 - 2i ：分母变成实数 1 2 + 2 2 。 乘以共轭 展开分子 乘回去验证 逐项检查选项"},
  "cx-locus-circle": {"t":"用模表示的圆","s":"设 $S$ 为满足 $|z - 3 - 4i| = 5$ 的复数 $z$ 的集合。<b>下列说法中正确的是？</b>","k":"设 S 为满足 |z - 3 - 4i| = 5 的复数 z 的集合。 下列说法中正确的是？ 复平面上的点 C = 3 + 4i 以及以它为圆心、半径为 5 的圆；圆经过原点。 |z - c| 表示 z 到 c 的距离。 把模看成距离 用坐标表示 检验各点 逐项检查选项"},
  "cx-modulus-product": {"t":"乘积的模","s":"设 $z = 3 + 4i$，$w = 1 - i$。<b>下列哪些等于 $|zw|$？</b>","k":"设 z = 3 + 4i ， w = 1 - i 。 下列哪些等于 |zw| ？ 复平面上的点 z = 3 + 4i、w = 1 − i 及其乘积 zw = 7 + i，各点都与原点相连。 可以先相乘再取模，也可以用 |zw| = |z|\\,|w| 。 相乘 取模 捷径：模相乘 逐项检查选项"},
  "cx-power-of-i": {"t":"i 的高次幂","s":"<b>下列哪些等于 $i^{2026}$？</b>","k":"下列哪些等于 i 2026 ？ 复平面上的单位圆及四个点 1、i、−1、−i；箭头表示每乘一次 i 就转四分之一圈。 i 4 = 1 ，所以只需看 2026 除以 4 的余数。 前几次幂 2026 落在周期的哪个位置 逐项检查选项"},
  "cx-quadratic-roots": {"t":"没有实根的二次方程","s":"<b>下列哪些是 $z^2 + 2z + 5 = 0$ 的解？</b>","k":"下列哪些是 z 2 + 2z + 5 = 0 的解？ 复平面上的两个根 −1 + 2i 和 −1 − 2i，关于实轴对称，都在以原点为圆心、半径为 √5 的圆上。 用求根公式；判别式为负，且 sqrt -16 = 4i 。 判别式 求根公式 用和与积验证 逐项检查选项"},
  "calc-pen-wall-40": {"t":"靠墙的最大围栏","s":"一位农民有 $40$ m 篱笆，要靠着一堵又长又直的墙围一个矩形围栏，因此只需围三条边。<b>围栏的面积最大是多少？</b>","k":"一位农民有 40 m 篱笆，要靠着一堵又长又直的墙围一个矩形围栏，因此只需围三条边。 围栏的面积最大是多少？ 上方是一堵长墙。矩形围栏靠墙；垂直于墙的两条边长为 x，平行于墙的边长为 y，共用篱笆 2x + y = 40 m。 设靠墙的两条边为 x ，则第三条边为 40 - 2x 。 建立模型 斜率为零的地方 验证这是最大值 最大面积 不用微积分 逐项检查选项"},
  "prob-two-dice-prime": {"t":"两颗骰子与质数","s":"掷两颗均匀的六面骰子，把两个点数相加。<b>下列哪些等于和为质数的概率？</b>","k":"掷两颗均匀的六面骰子，把两个点数相加。 下列哪些等于和为质数的概率？ 一个 6 × 6 的表格：列是第一颗骰子（1–6），行是第二颗骰子（1–6），每格显示两数之和。 列出所有和的 6 6 表：每一格的可能性相同。 所有结果 哪些和是质数？ 数出符合条件的格子 概率 逐项检查选项"},
  "nt-last-digit-7-2026": {"t":"巨大数的个位","s":"$7^{2026}$ 有 1700 多位数字。<b>它的个位数字是下列哪一个？</b>","k":"7 2026 有 1700 多位数字。 它的个位数字是下列哪一个？ 7 的幂的个位数字循环图：7¹ 个位是 7，7² 是 9，7³ 是 3，7⁴ 是 1，然后循环重复。 写出 7, 7 2, 7 3, 的个位数字，寻找规律。 只有个位数字重要 每 4 个循环一次 2026 落在周期的哪个位置 用同余验证 逐项检查选项"}
});
